const AISourceCore={
 path:'resources/ui/assistant-copy.json',
 request:'把 Relay 内置助手的开场说明改成「先说目标，我们一起完成。」；保留其他功能，运行测试并展示结果。',
 goal(text){if(typeof text!=='string'||text.length>1800||!/助手/.test(text)||!/开场|欢迎/.test(text)||!/改|换|设/.test(text))throw new Error('本地课程只支持“把内置助手开场说明改成「新文案」”；其他目标请在准备真实AI后执行。');const m=text.match(/[「“]([^」”\n]{1,160})[」”]/);if(!m)throw new Error('请用「」写明新开场文案，例如「先说目标，我们一起完成。」');return m[1].trim();},
 edit(read,welcome){if(read.manualDraft)throw new Error('源码存在未保存的人工草稿，请先处理；没有覆盖它。');if(read.nextStart!==null)throw new Error('先完整读取文案源码');const copy=JSON.parse(read.text);if(typeof copy.welcome!=='string')throw new Error('实际源码没有开场文案字段');return{oldText:JSON.stringify(copy.welcome),newText:JSON.stringify(welcome),expectedHash:read.hash,path:read.path,original:copy.welcome};},
 plan(goal){const ref=(id,key)=>({$ref:key?id+'.'+key:id}),w=ref('s1','workspaceId');return[
  ['relay.lesson.prepare','准备独立的 Relay 源码副本',{welcome:goal}],
  ['dev.open','展开实际源码工作区',{workspaceId:w}],
  ['dev.read','读取 Relay 助手文案源码',{workspaceId:w,path:this.path}],
  ['dev.read','读取本课测试和验收代码',{workspaceId:w,path:'tests/relay-welcome.test.mjs'}],
  ['relay.lesson.edit','依据实际原文和版本准备最小修改',{read:ref('s3',''),welcome:goal}],
  ['dev.replace','实际写入新的助手开场说明',{workspaceId:w,path:this.path,oldText:ref('s5','oldText'),newText:ref('s5','newText'),expectedHash:ref('s5','expectedHash')}],
  ['dev.check','运行真实的本地测试',{workspaceId:w,command:'test'}],
  ['dev.diff','核对修改前后的真实差异',{workspaceId:w,changeId:ref('s6','id')}],
  ['dev.preview','从已修改源码展示真实组件预览',{workspaceId:w}],
  ['relay.lesson.verify','核对源码、测试与显示结果',{workspaceId:w,welcome:goal}]
 ].map(([name,label,args],i)=>({id:'s'+(i+1),name,label,args,status:'pending',effect:'local'}));},
 verified(preview,check,goal){return!!preview&&preview.welcome===goal&&check?.status==='passed'&&check.exitCode===0&&check.sourceHash===preview.hash;},
 draft(t,text){if(t.status==='prepared')t.preparedDraft=text;else if(t.assistantId)t.followupDraft=text;else t.request=text;},
 stage(t,s,busy,draft){if(!t)return null;if(!t.assistantId)return{selector:draft?.trim()?'#guide [data-as-send]':'#as-input',number:draft?.trim()?2:1};if(busy)return{selector:'#guide [data-as-pause]',number:3};if(s?.status==='paused'||s?.status==='waiting'||s?.status==='failed')return{selector:'#guide [data-as-continue]',number:3};if(t.rolledBack)return{selector:'#guide [data-aid-leave]',number:6};if(t.verified)return{selector:'#guide [data-aid-rollback]',number:5};return null;},
 retry(checkpoint,check){if(!check.settled)throw new Error('上一轮检查仍在停止，请等待进程结束');if(['stopped','interrupted','failed'].includes(check.status)){delete checkpoint.devRunId;delete checkpoint.devRequestId;return true;}return false;}
};
