const aidFetchBase=window.fetch.bind(window);window.fetch=function(input,options={}){const url=typeof input==='string'?input:input?.url||String(input),body=typeof options.body==='string'?options.body:'';if((aidActive()||B()?.aiSourcePractice)&&(/\/api\/studio\/(assistant|guide|refine)(?:\?|$)/.test(url)||/\/api\/studio\/models(?:\?|$)/.test(url)&&/"action"\s*:\s*"(?:run|check)"/.test(body)||/\/api\/studio\/collaboration(?:\?|$)/.test(url)&&/"action"\s*:\s*"(?:start|resume)"/.test(body)))return Promise.reject(new Error('当前为本地AI自开发课程，不运行模型。请用“准备真实AI开发”回到自己的仓库，明确配置和开工。'));return aidFetchBase(input,options)};
