async function aidPrepareLab(welcome,ctx){const t=aidCourse(),cp=ctx.step.checkpoint=ctx.step.checkpoint||{};if(!t||ctx.session.aiSelfdev!==t.id)throw new Error('本地课程已结束');
 if(!t.boardId||!state.boards.some(b=>b.id===t.boardId)){ACT['board.create']({name:'自然语言开发 Relay · 本地演练'});t.boardId=state.activeBoard;B().tutorialSessionId=t.id;B().sourcePractice=true;B().aiSourcePractice=true;}
 if(!P(t.projectId)){const old=new Set(state.projects.map(p=>p.id));ACT['project.create']({name:'Relay · AI 自开发演练'});const p=state.projects.find(p=>!old.has(p.id));t.projectId=p.id;p.summary='软件操作助手读取正式文案源码的独立副本、最小修改、真实测试、界面预览与回滚；本轮不运行模型。';p.tutorialSessionId=t.id;}
 save();const w=await dwApi('practice',{boardId:t.boardId,projectId:t.projectId,requestId:t.requestId,scenario:'relay-assistant',expectedWelcome:welcome});ctx.signal.throwIfAborted();t.workspaceId=w.id;ctx.session.boardId=t.boardId;DW.current=w.id;DW.projectId=t.projectId;DW.settings=false;DW.uiPreview=null;DW.file=null;DW.query='';DW.page=1;await dwRefresh();closePan();save();renderAll();return{workspaceId:w.id,boardId:t.boardId,projectId:t.projectId,source:w.practice.source,message:'已创建隔离的真实 Relay 文案源码副本；原仓库与安装包保留'};}
const aidInvokeBase=asInvoke;asInvoke=async function(name,a,ctx){const t=aidCourse();if(!ctx.session.aiSelfdev)return aidInvokeBase(name,a,ctx);ctx.signal.throwIfAborted();await asDelay(500,ctx.signal);let r;
 if(name==='relay.lesson.prepare')r=await aidPrepareLab(a.welcome,ctx);
 else if(name==='relay.lesson.edit')r={...AISourceCore.edit(a.read,a.welcome),message:'已从实际读取结果取得原文、替换内容和版本 hash'};
 else if(name==='relay.lesson.verify'){const p=ctx.session.results.s9,c=ctx.session.results.s7;if(!AISourceCore.verified(p,c,a.welcome))throw new Error('源码、检查与预览未对上同一版本，不能报告完成');t.verified=true;t.preview=p;const project=P(t.projectId);if(project&&!project.artifacts.some(x=>x.aiSelfdevId===ctx.session.id))project.artifacts.push({id:'a'+uid(),name:'Relay 自开发演练结果',done:true,text:'【本地课程 · 未运行AI模型】\n用户需求：'+ctx.session.request+'\n源码：'+AISourceCore.path+'\n测试：退出码0\n修改ID：'+ctx.session.results.s6.id+'\n预览版本：'+p.hash+'\n只修改独立副本，未替换安装包。',aiSelfdevId:ctx.session.id});r={projectId:t.projectId,workspaceId:t.workspaceId,hash:p.hash,message:'真实修改、测试通过与组件预览已核对，成果记录已保存在项目内'};}
 else{r=await aidInvokeBase(name,a,ctx);if(name==='dev.check'&&r.status!=='passed')throw asWaiting('检查'+r.status+'，未通过；明确继续后可重跑本地检查，已完成的读取与修改不重做');}
 if(name==='dev.read'&&a.path===AISourceCore.path&&!t.baselineHash){t.baselineHash=r.hash;t.originalWelcome=JSON.parse(r.text).welcome;}
 if(ctx.session.rollbackSelfdev&&name==='dev.preview'){if(r.hash!==t.baselineHash||r.welcome!==t.originalWelcome)throw new Error('回滚后尚未恢复原源码，不能标记完成');t.rolledBack=true;t.verified=false;t.preview=r;}
 if(t.stepMode&&ctx.session.cursor<ctx.session.steps.length-1)asPause();return r;
};
const aidExecuteBase=asExecute;asExecute=async function(s,approve=false,...rest){if(s?.aiSelfdev){const t=aidCourse();if(!t||s.aiSelfdev!==t.id||t.status!=='active')return hint('请先从教程目录继续本地AI自开发课程');if(t.boardId&&state.activeBoard!==t.boardId){state.activeBoard=t.boardId;state.room=null;state.sel=t.projectId;renderAll();}if(!t.baselineHash&&s.results?.s3?.hash){t.baselineHash=s.results.s3.hash;t.originalWelcome=JSON.parse(s.results.s3.text).welcome;save();}const step=s.steps[s.cursor];if(step?.name==='dev.check'&&step.checkpoint?.devRunId){const c=await dwApi('checkStatus',{workspaceId:t.workspaceId,runId:step.checkpoint.devRunId});if(AISourceCore.retry(step.checkpoint,c))s.reason='按你的继续操作重新运行本地检查；其他完成步骤保留';}AID.sourceFocus=false;}return aidExecuteBase(s,approve,...rest)};
const aidAskBase=asAsk;asAsk=async function(text){if(!aidActive()){if(aidCourse()?.status==='prepared'&&state.activeBoard===aidCourse().preparedBoardId){await dwRefresh();const w=dwVisible().find(w=>w.kind!=='practice'&&w.writable&&w.checksAllowed);if(!w){AS.localReply='先连接真实仓库并核对源码写入与检查脚本权限；尚未调用模型。';renderGuide();return;}}if(aidCourse()?.status==='prepared'){aidCourse().status='complete';save();}return aidAskBase(text);}const t=aidCourse();if(t.assistantId){AS.localReply='本地课程仅执行当前文案需求。你可以继续、查看结果或回滚；开放式新需求请使用“准备真实AI开发”，不会自动发给模型。';renderGuide();return;}try{const welcome=AISourceCore.goal(text);t.request=text;t.goal=welcome;const s={id:'as'+uid(),aiSelfdev:t.id,demo:true,request:text,reply:'【本地课程 · 未运行模型】仅提取本课引号内的开场文案，按公开的演练步骤调用正式源码工具；其他目标不执行。',steps:AISourceCore.plan(welcome),cursor:0,status:'ready',createdAt:Date.now()};t.assistantId=s.id;state.assistantSessions.push(s);AS.current=s.id;AS.draft='';save();await asExecute(s);}catch(e){AID.error=e.message;renderGuide();}};
