function aidReceipt(step,s){const r=step.result;if(!r)return'';let text;if(step.name==='dev.read')text=r.text;else if(step.name==='dev.diff')text='修改前\n'+r.before?.text+'\n修改后\n'+r.after?.text;else if(step.name==='dev.check')text=(r.message||'')+'\n'+(r.outputTail||'');else if(step.name==='relay.lesson.edit')text='原文片段：'+r.oldText+'\n替换为：'+r.newText+'\n基于版本：'+r.expectedHash;else if(step.name==='dev.preview')return `<details class="aid-receipt" open><summary>实际源码组件预览</summary>${renderAssistantWelcome(r.welcome)}<small>版本 ${esc(r.hash.slice(0,12))} · ${r.test?.status==='passed'&&r.test.sourceHash===r.hash?'该版本测试已通过':'该版本尚未验证'} · 未替换安装包</small></details>`;else text=JSON.stringify(r,null,2);return `<details class="aid-receipt" ${step===s.steps.filter(x=>x.status==='done').at(-1)?'open':''}><summary>查看本步真实回执</summary><pre>${esc(String(text||'').slice(0,2200))}</pre></details>`;}
