document.addEventListener('input',e=>{if(e.target.id==='as-input'&&(aidActive()||aidCourse()?.status==='prepared')){AISourceCore.draft(aidCourse(),e.target.value);save();}});
document.addEventListener('change',e=>{if(e.target.matches('[data-aid-step]')){aidCourse().stepMode=e.target.checked;save();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-aid-begin],[data-aid-source],[data-aid-rollback],[data-aid-leave],[data-aid-real],[data-aid-back],[data-aid-connect],[data-aid-exit]');if(!b)return;e.preventDefault();void(async()=>{if(b.hasAttribute('data-aid-exit')){aidCourse().status='complete';save();renderGuide();return;}if(b.hasAttribute('data-aid-connect')){if(innerWidth<950)$('#guide').classList.remove('o');await dwOpen(state.room||state.sel);DW.settings=true;DW.preview=null;DW.directory=dwWorkspace()?.root||'';dwRender();return;}if(b.hasAttribute('data-aid-begin'))return aidBegin();if(b.hasAttribute('data-aid-leave'))return aidLeave();if(b.hasAttribute('data-aid-real'))return aidLeave(true);if(b.hasAttribute('data-aid-rollback'))return aidRollback();if(b.hasAttribute('data-aid-source')){asPause();while(AS.ac)await new Promise(r=>setTimeout(r,30));AID.sourceFocus=true;document.body.classList.add('aid-source-focus');if(innerWidth<950)$('#guide').classList.remove('o');await dwOpen(aidCourse().projectId);if(aidCourse().preview){DW.uiPreview=aidCourse().preview;dwRender();}return;}if(b.hasAttribute('data-aid-back')){if(innerWidth<950)dwClose();AID.sourceFocus=false;document.body.classList.remove('aid-source-focus');$('#guide').classList.add('o');renderGuide();}})().catch(e=>{AID.error=e.message;hint(e.message);renderGuide()})},true);
function aidDraw(){if(!aidActive()||!$('#guide').classList.contains('o')||tutorialHome.open){if(dmArrow.dataset.aidPointer){dmArrow.style.display='none';tutorialSpot.hidden=true;delete dmArrow.dataset.aidPointer;}return;}const step=AISourceCore.stage(aidCourse(),asSession(),!!AS.ac,AS.draft);dmArrow.style.display='none';tutorialSpot.hidden=true;if(!step)return;const target=tutorialPointerTarget(step.selector);if(!target)return;const r=dtVisibleRect(target);if(!r)return;const p=TutorialPointerCore.anchor(r,innerWidth,innerHeight);if(!p)return;Object.assign(tutorialSpot.style,{left:r.left-4+'px',top:r.top-4+'px',width:r.width+8+'px',height:r.height+8+'px'});tutorialSpot.hidden=false;dmArrow.dataset.aidPointer='true';dmArrow.dataset.guideTarget=step.selector;dmArrow.dataset.guideOperation=String(step.number);dmArrow.setAttribute('viewBox',`0 0 ${innerWidth} ${innerHeight}`);dmArrow.innerHTML=`<title>自然语言自开发操作 ${step.number}</title><defs><marker id="aid-head" viewBox="0 0 10 10" markerWidth="7" markerHeight="7" refX="9" refY="5" orient="auto"><path d="M1 1 L9 5 L1 9" fill="#F7C948" stroke="#1B2230"/></marker></defs><path d="M${p.sx} ${p.sy} L${p.tx} ${p.ty}" stroke="#1B2230" stroke-width="3" marker-end="url(#aid-head)"/><circle cx="${p.sx}" cy="${p.sy}" r="15" fill="#F7C948" stroke="#1B2230"/><text x="${p.sx}" y="${p.sy}" dy=".35em" text-anchor="middle" font-family="system-ui" font-size="12" fill="#1B2230">${step.number}</text>`;dmArrow.style.display='block';}
const aidPointerBase=tutorialPointerDraw;tutorialPointerDraw=function(){aidPointerBase();aidDraw();};setInterval(()=>{if(aidActive()||dmArrow.dataset.aidPointer)aidDraw()},450);
/* AI_SOURCE_TUTORIAL_END */
